sys_script.script:
(function executeRule(current, previous) {
    var employee = current.getValue('employee');
    var leaveType = current.getValue('leave_type');
    var duration = parseFloat(current.getValue('duration') || '0');
    if (!employee || !leaveType || duration <= 0) return;

    var year = new GlideDateTime().getYearLocalTime();
    var balGr = new GlideRecord('x_2316161_bjit_e_0_lv_bal');
    balGr.addQuery('employee', employee);
    balGr.addQuery('leave_type', leaveType);
    balGr.addQuery('year', year);
    balGr.addQuery('active', true);
    balGr.query();

    if (balGr.next()) {
        var remaining = parseFloat(balGr.getValue('remaining_days') || '0');
        if (duration > remaining) {
            gs.addErrorMessage('Insufficient leave balance. You have ' + remaining + ' day(s) remaining but requested ' + duration + ' day(s).');
            current.setAbortAction(true);
        }
    } else {
        // Check if it's unpaid leave type (no balance needed)
        var ltGr = new GlideRecord('x_2316161_bjit_e_0_lv_type');
        if (ltGr.get(leaveType) && ltGr.getValue('paid') == '1') {
            gs.addErrorMessage('No leave balance found for this leave type in the current year. Please contact HR.');
            current.setAbortAction(true);
        }
    }
})(current, previous);
